// Test script to verify credentials

const { Client } = require('pg');
const axios = require('axios');

// Database connection
const dbClient = new Client({
  connectionString: process.env.DATABASE_URL,
});

dbClient.connect()
 .then(() => {
    console.log('Connected to the database');
    dbClient.end();
  })
 .catch(err => {
    console.error('Database connection failed', err.stack);
  });

// AWS API test
axios.get('https://s3.amazonaws.com/', {
  auth: {
    username: process.env.AWS_ACCESS_KEY_ID,
    password: process.env.AWS_SECRET_ACCESS_KEY,
  },
})
 .then(response => {
    console.log('AWS API test successful');
  })
 .catch(error => {
    console.error('AWS API test failed', error);
  });

// Anthropic API test
axios.get('https://api.anthropic.com/v1/models', {
  headers: {
    'x-api-key': process.env.ANTHROPIC_API_KEY,
  },
})
 .then(response => {
    console.log('Anthropic API test successful');
  })
 .catch(error => {
    console.error('Anthropic API test failed', error);
  });

// Stripe API test
axios.get('https://api.stripe.com/v1/balance', {
  headers: {
    'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`,
  },
})
 .then(response => {
    console.log('Stripe API test successful');
  })
 .catch(error => {
    console.error('Stripe API test failed', error);
  });

// Logfire API test
axios.post('https://api.logfire.com/v1/logs', { message: 'Test log' }, {
  headers: {
    'Authorization': `Bearer ${process.env.LOGFIRE_TOKEN}`,
  },
})
 .then(response => {
    console.log('Logfire API test successful');
  })
 .catch(error => {
    console.error('Logfire API test failed', error);
  });

